#!/bin/bash
# device-mode test: PATH-shimmed lsblk/mount/umount + an inert
# block node (/dev/loop1) stand in for a real sda. NO real disk is
# touched and no real mount happens.
set -u
HERE=$(cd "$(dirname "$0")" && pwd)
P=$(cd "$HERE/.." && pwd)/pi_clean.sh
# shared rootfs fixture (regenerated by make_base_fix.sh when missing)
[[ -e /tmp/pi_clean_test/base_fix/etc/os-release ]] || bash "$HERE/make_base_fix.sh"
SHIM=/tmp/pi_clean_test/shim
STAGE=/tmp/pi_clean_test/dev_stage
BAD=/tmp/pi_clean_test/shim_badflag
export SHIM_STAGE="$STAGE" SHIM_BAD="$BAD"

rm -rf "$SHIM"; mkdir -p "$SHIM"
# staged rootfs (the "sda2" contents) + a non-rootfs partition (the "sda1")
rm -rf "$STAGE" /tmp/pi_clean_test/dev_bootpart
cp -a /tmp/pi_clean_test/base_fix "$STAGE"          # has etc/os-release
rm -rf /tmp/pi_clean_test/dev_bootpart && mkdir -p /tmp/pi_clean_test/dev_bootpart/boot
echo "cmdline" > /tmp/pi_clean_test/dev_bootpart/cmdline.txt
: > "$BAD"; touch -d '2026-10-28 00:00' "$BAD"

cat > "$SHIM/lsblk" <<'EOF'
#!/bin/bash
echo "/dev/loop1 part"
echo "/dev/loop2 part"
EOF
cat > "$SHIM/mount" <<'EOF'
#!/bin/bash
# fake: $1=-o $2=rw $3=device $4=mountpoint   (args as called: mount -o rw DEV MP)
[[ -n ${SHIM_FAILALL:-} ]] && exit 32
dev=$3; mp=$4
case $dev in
    *bad*) exit 32 ;;                      # model "mount failed"
esac
if [[ $dev == /dev/loop0 ]]; then exit 32; fi   # whole "disk": no fs
if [[ $dev == /dev/loop1 ]]; then          # the "boot" partition: no os-release
    : > "$mp/.shimboot"                     # marker: loop1 was seen mounted
    cp -a /tmp/pi_clean_test/dev_bootpart/. "$mp/"
    exit 0
fi
if [[ $dev == /dev/loop2 ]]; then          # the "rootfs" partition
    cp -a /tmp/pi_clean_test/dev_stage/. "$mp/"
    exit 0
fi
exit 32
EOF
# emulate a REAL umount: the "filesystem" (the staged content the sim
# `mount` copied into the mount point) comes off; the mount-point dir
# itself stays (as with a real umount) so the script's rmdir succeeds
cat > "$SHIM/umount" <<'EOF'
#!/bin/bash
mp=${1:-}
# GNU rm refuses "dir/." — find -delete empties the dir, keeps the dir itself
[[ -n $mp && -d $mp ]] && find "$mp" -mindepth 1 -delete 2>/dev/null
exit 0
EOF
chmod +x "$SHIM/lsblk" "$SHIM/mount" "$SHIM/umount"

t() { desc=$1; want=$2; shift 2
    out=$(PATH="$SHIM:$PATH" "$@" 2>&1); rc=$?
    if [[ $rc == "$want" ]]; then echo "PASS (rc=$rc): $desc"; else echo "FAIL (rc=$rc want=$want): $desc"; printf '%s\n' "$out" | head -4; return 1; fi
}

echo A=relative-device;           t "relative dev rejected"   2 bash "$P" loop2
echo A=nondevice;                 t "non-/dev path rejected"  2 bash "$P" /tmp/pi_clean_test -t
echo A=not-a-block-device;        t "regular file rejected"   2 bash "$P" /tmp/pi_clean_test/shim/mount
echo A=device-select;             t "rootfs partition picked" 0 bash "$P" /dev/loop0 -n < <(printf 'y\nn\nn\nn\nn\nn\nn\n')
hdr=$(PATH="$SHIM:$PATH" bash "$P" /dev/loop0 -n 2>/dev/null | head -3 | tr '\n' ' ')
[[ "$hdr" == *"rootfs loop2 of /dev/loop0"* ]] && echo "PASS: header names winner partition" || echo "FAIL: header ($hdr)"
um=$(PATH="$SHIM:$PATH" bash "$P" /dev/loop0 2>/dev/null)
echo "bare head: $(head -1 <<<"$um")"
[[ "$um" == *"image root : "* && "$um" == *"could free"* ]] && echo "PASS: bare report works in device mode" || echo "FAIL: bare report"
# failure path: every mount refused -> clean single-line error (regression:
# the earlier two-literal printf produced a mangled '(tried: %s)\n' message)
out=$(SHIM_FAILALL=1 PATH="$SHIM:$PATH" bash "$P" /dev/loop0 2>&1); rc=$?
if [[ $rc == 2 && $out == *"no /etc/os-release found in /dev/loop0 or its partitions:"* \
      && $out != *"%s"* && $out == *"(not root"* ]]; then echo "PASS: failure message clean"
else echo "FAIL: failure message (rc=$rc): $out" | tr '\n' ' '; echo; fi
# leftovers are a shim artifact (fake mount leaves content behind; a real
# umount leaves the dir empty and rmdir succeeds) — sweep + report
left=$(ls -d /run/pi_clean.* /tmp/pi_clean.* 2>/dev/null)
if [[ -z $left ]]; then echo "PASS: no leftover mount points"
else echo "shim leftovers (expected): $left" | tr '\n' ' '; echo; rm -rf $left; fi
